constexpr int square(int x) { return x * x; }

int main() {
  constexpr int a = 10;
  constexpr int b = square(a); // Compile-time calculation
  int c = square(15); // Runtime calculation
  int d = square(some_runtime_variable); //Runtime calculation
  std::cout << b << " " << c << " " << d << std::endl;
  return 0;
}
